import { Assets } from '~/game/util/assets';
export function StageFactory(props) {
    const stage = {
        name: props.name
    };
    stage.render = render.bind(stage);
    return stage;
}
function render(context) {
    context.drawImage(Assets.stageSprite, 0, 0, 240, 224);
    //240x224 pixels
}
