export function BonusFactory(props) {
    return BONUS[props.bonus](props);
}
function BombBonus(props) {
    const bomb = {
        axes: props.axes,
        bonus: props.bonus,
        t: 'B',
        x: props.x,
        y: props.y,
        tick: (state) => {
            collided(state, bomb, () => {
                state.players.myself.bombs++;
            });
        },
        render: (context) => {
            context.drawImage(Assets.bombSprite, 0, 0, TILE_SIZE, TILE_SIZE, bomb.x, bomb.y, TILE_SIZE, TILE_SIZE);
        }
    };
    return bomb;
}
