function SpeedBonus(props) {
    const speed = {
        axes: props.axes,
        bonus: props.bonus,
        t: 'B',
        x: props.x,
        y: props.y,
        tick: (state) => {
            collided(state, speed, () => {
                if (state.players.myself.speed < MAX_SPEED)
                    state.players.myself.speed += 0.1;
            });
        },
        render: (context) => {
            context.drawImage(Assets.bonusSprite, 0, 48, TILE_SIZE, TILE_SIZE, speed.x, speed.y, TILE_SIZE, TILE_SIZE);
        }
    };
    return speed;
}
